SELECT p.gender, i.first_careunit, i.intime, i.outtime, i.los, p.anchor_age, p.anchor_year, p.anchor_year_group, s.spo2, COUNT(s.spo2) AS N, AVG(s.spo2) AS mean, MEDIAN(s.spo2) AS median, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY s.spo2) - PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY s.spo2) AS interquartile_range, SUM(CASE WHEN s.spo2 < 90 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(s.spo2), 0) AS akireported FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN chartevents s ON i.stay_id = s.stay_id AND i.hadm_id = s.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 90 AND 100 AND i.first_careunit = 'ICU' AND i.intime <= '2020-01-01' AND i.outtime >= '2020-12-31' AND s.itemid = 8716780 AND s.valueuom = 'SpO2' GROUP BY p.gender, i.first_careunit, i.intime, i.outtime, i.los, p.anchor_age, p.anchor_year, p.anchor_year_group, s.spo2;